"""
    input: [7, 1, 5, 3, 6, 4]
    diff : [X, -6, 4, -2, 3, -2]
    :type prices: List[int]
    :rtype: int
    """
def max_profit_optimized(prices: Any) -> object {
    (cur_max, max_so_far) = (0, 0);
    for i in range(1, len(prices)) {
        cur_max = max(0, ((cur_max + prices[i]) - prices[(i - 1)]));
        max_so_far = max(max_so_far, cur_max);
    }
    return max_so_far;
}

"""
    For example: [194, 106]
    note: summation( p_j * (1 - p_j) ) = 1 - summation( p_j^2 )
    """
def Gini_impurity(splitted_sample: Any = []) -> object {
    denominator = sum(splitted_sample);
    if (denominator == 0) {
        return 0;
    }
    Gini_index = 0;
    for numerator_i in range(len(splitted_sample)) {
        p_i = splitted_sample[numerator_i] / denominator;
        Gini_index += p_i * (1 - p_i);
    }
    return Gini_index;
}

"""Translate urls into human-readable filenames."""
def clean_paths(url: Any) -> object {
    to_remove = ['http://', 'https://', 'www.', '.com', '.json', '.'];
    for item in to_remove {
        url = url.replace(item, '');
    }
    return url.replace('/', '_');
}

