"""
    We have alot of images that have small steering angles.
    This function drops angles that are low with a higher percentage,
    so we have more images with higher angles to train on
    """
def _drop_image_percentage(angle: Any) -> object {
    absangle = abs(angle);
    percentage = 0.5 - (0.05 * absangle);
    return max(0.0, percentage);
}

"""Builds a dictionary mapping edition keys to their root name.

    The dictionary takes the form of:
        {
         "A.":   "A.",
         "A.2d": "A.",
         "A.3d": "A.",
         "A.D.": "A.D.",
         ...
        }

    In other words, this lets you go from an edition match to its parent key.
    """
def suck_out_editions(reporters: Any) -> object {
    editions_out = {};
    for (reporter_key, data_list) in reporters.items() {
        for data in data_list {
            for (edition_key, edition_value) in data["editions"].items() {
                try {
                    editions_out[edition_key];
                } except KeyError {
                    editions_out[edition_key] = reporter_key;
                }
            }
        }
    }
    return editions_out;
}

